var po = new JParamObject();
var createBy = po.getEnv("UserCaption");
var dataSet = AGGrid1.getSelectedDataSet();
if(dataSet == null){
    window.showAlertMsg('系统提示', '请选择数据', '1', '确定', null);
    return 0;
}
var count = dataSet.getRowCount();
var codes = "";
if(count >0){
    for(var i = 0;i<count;i++){
        var row = dataSet.getRowSet(i);
        var F_GUID = row.getValue("F_GUID","");
        if(i==count-1){
            codes+=F_GUID;
        }else{
            codes+=F_GUID+",";
        }
    }
}

